import {predict,validate,parseCSV,evaluate,limits} from './inference.mjs';
const $=id=>document.getElementById(id),pct=n=>(n*100).toFixed(1)+'%',labels=['Packet size (bytes)','Flow duration (ms)','Packets per second','Failed login attempts','Unique ports','Outbound volume (KB)','SYN packet ratio','Error rate'];
let model,data,session=[],threshold=.5,timer=null,cursor=0,sequence=0,selected=null,batch=[],lastLatency=0;
const defaults=[650,600,25,0,4,70,.15,.05];
function message(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500);}
function page(name){if(!['monitor','analyze','model','project'].includes(name))name='monitor';document.querySelectorAll('.page').forEach(e=>e.classList.toggle('active',e.id===name));document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.page===name));$('breadcrumb').textContent=document.querySelector(`nav button[data-page="${name}"]`).textContent.trim().slice(1).trim();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{location.hash=b.dataset.page;page(b.dataset.page)});window.addEventListener('hashchange',()=>page(location.hash.slice(1)));page(location.hash.slice(1));
function download(name,contents,type='application/json'){const u=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function score(values){const t=performance.now();const p=predict(model,values);lastLatency=performance.now()-t;return p;}
function tick(){const pool=$('scenario').value==='all'?data:data.filter(r=>r.scenario===$('scenario').value);if(!pool.length)return;const sample=pool[cursor++%pool.length];const p=score(sample.values);sequence++;session.push({id:`OBS-${String(sequence).padStart(5,'0')}`,time:new Date().toISOString(),values:sample.values,probability:p,scenario:sample.scenario,label:sample.label,reviewed:false,source:`10.0.${sequence%4}.${10+sequence%200}`,destination:`10.1.0.${1+sequence%5}`});if(session.length>2000)session.shift();render();}
function stop(){clearInterval(timer);timer=null;$('play').textContent='Resume replay';$('streamStatus').innerHTML='<i class="dot"></i> REPLAY PAUSED';}
$('play').onclick=()=>{if(timer){stop();return;}tick();timer=setInterval(tick,Number($('speed').value));$('play').textContent='Pause replay';$('streamStatus').innerHTML='<i class="dot"></i> REPLAY RUNNING';};
$('speed').onchange=()=>{if(timer){clearInterval(timer);timer=setInterval(tick,Number($('speed').value));}};$('scenario').onchange=()=>{cursor=0;message('Scenario updated for the next flow.');};
$('reset').onclick=()=>{stop();session=[];sequence=0;cursor=0;$('play').textContent='Start live replay';$('streamStatus').innerHTML='<i class="dot"></i> REPLAY READY';render();};
function render(){const total=session.length,anomalies=session.filter(r=>r.probability>=threshold).length,normal=total-anomalies;$('flows').textContent=total.toLocaleString();$('anomalies').textContent=anomalies;$('rate').textContent=total?pct(anomalies/total)+' of retained session flows':'Awaiting traffic';$('latency').textContent=total?lastLatency.toFixed(2)+' ms':'—';$('normalPercent').textContent=total?pct(normal/total):'—';$('normalCount').textContent=normal;$('anomalyCount').textContent=anomalies;$('donut').style.background=total?`conic-gradient(#279c7d 0 ${normal/total*100}%,#db8b48 ${normal/total*100}% 100%)`:'#e8eef0';$('thresholdLabel').textContent='Decision threshold '+threshold.toFixed(2);drawTimeline();renderRows();}
function drawTimeline(){const rows=session.slice(-50),w=680,h=138,left=30,top=12;let s='';for(let i=0;i<=4;i++){const y=top+i*h/4;s+=`<line x1="30" y1="${y}" x2="710" y2="${y}" stroke="#eaf0f3"/><text x="0" y="${y+4}" font-size="9" fill="#91a0ac">${(1-i/4).toFixed(2)}</text>`;}const y=top+(1-threshold)*h;s+=`<line x1="30" y1="${y}" x2="710" y2="${y}" stroke="#d99a63" stroke-dasharray="4 5"/>`;if(rows.length){const pts=rows.map((r,i)=>[left+i*w/49,top+(1-r.probability)*h]);s+=`<polygon points="${left},${top+h} ${pts.map(p=>p.join(',')).join(' ')} ${pts.at(-1)[0]},${top+h}" fill="#e1f3eb" opacity=".8"/><polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#27a584" stroke-width="2"/>`;pts.forEach((p,i)=>{if(rows[i].probability>=threshold)s+=`<circle cx="${p[0]}" cy="${p[1]}" r="3.5" fill="#dd8b48"/>`;});}else{s+='<text x="370" y="85" text-anchor="middle" fill="#98a5af" font-size="12">Waiting for the first flow</text>';} $('timeline').innerHTML=s;}
function renderRows(){const filtered=session.filter(r=>$('filter').value==='all'||($('filter').value==='anomaly')===(r.probability>=threshold));$('rowCount').textContent=filtered.length;$('trafficRows').innerHTML=filtered.slice(-12).reverse().map(r=>`<tr data-id="${r.id}" tabindex="0" role="button" aria-label="Inspect ${r.id}"><td>${r.id}<small>${new Date(r.time).toLocaleTimeString()}</small></td><td>${r.source} <span style="color:#9aa8b2">→</span> ${r.destination}</td><td>${r.values[2].toFixed(1)}</td><td>${r.probability.toFixed(3)}<span class="score-bar"><i style="width:${r.probability*100}%"></i></span></td><td><span class="badge ${r.probability>=threshold?'warn':''}">${r.probability>=threshold?'Anomaly':'Normal'}</span></td><td>${r.reviewed?'Reviewed':'Inspect'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No flows match this view. Start replay or change the filter.</td></tr>';document.querySelectorAll('tr[data-id]').forEach(r=>{r.onclick=()=>openFlow(r.dataset.id);r.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openFlow(r.dataset.id);}};});}
$('filter').onchange=renderRows;
function openFlow(id){selected=session.find(r=>r.id===id);if(!selected)return;$('detailTitle').textContent=id;const r=selected;$('detailBody').innerHTML=`<span class="badge ${r.probability>=threshold?'warn':''}">${r.probability>=threshold?'Anomaly':'Normal'} · score ${r.probability.toFixed(4)}</span><p style="margin-top:15px">The forest averages the anomaly probabilities of 40 trees. Current threshold: ${threshold.toFixed(2)}. This score is a model estimate, not proof of an attack.</p><table>${r.values.map((v,i)=>`<tr><td>${labels[i]}</td><td>${v.toLocaleString()}</td></tr>`).join('')}</table><p><b>Generator profile:</b> ${r.scenario} (ground truth, excluded from model inputs). Review feature values and corroborate with authorized network logs before taking action.</p>`;$('ack').textContent=r.reviewed?'Reviewed':'Mark reviewed';$('flowDialog').showModal();}
$('closeDialog').onclick=()=>$('flowDialog').close();$('ack').onclick=()=>{if(selected){selected.reviewed=true;renderRows();$('flowDialog').close();message('Flow marked reviewed for this session.');}};
$('export').onclick=()=>{if(!session.length){message('Start replay before exporting a session.');return;}download('sentinel-session.json',JSON.stringify({model:model.version,source:'Synthetic replay; no packet capture',threshold,retained_flows:session.length,total_seen:sequence,exported_at:new Date().toISOString(),flows:session.map(r=>({...r,prediction:r.probability>=threshold?'anomaly':'normal'}))},null,2));};
function modelView(){const m=evaluate(data,threshold);$('cutoff').textContent=threshold.toFixed(2);$('dynamicMetrics').innerHTML=['accuracy','precision','recall','f1'].map(k=>`<div><b>${pct(m[k])}</b><span>${k.toUpperCase()}</span></div>`).join('');$('confusion').innerHTML=`<table><thead><tr><th>ACTUAL / PREDICTED</th><th>NORMAL</th><th>ANOMALY</th></tr></thead><tbody><tr><td>Normal</td><td>${m.tn} TN</td><td>${m.fp} FP</td></tr><tr><td>Anomaly</td><td>${m.fn} FN</td><td>${m.tp} TP</td></tr></tbody></table>`;}
$('threshold').oninput=()=>{if(!data)return;threshold=Number($('threshold').value);modelView();render();if(batch.length){batch=[];$('downloadBatch').disabled=true;$('csvStatus').textContent='Threshold changed. Upload the CSV again to calculate new predictions.';}$('prediction').textContent='Threshold changed. Analyze the flow again for an updated decision.';};
$('predictForm').onsubmit=e=>{e.preventDefault();if(!model)return;const values=labels.map((_,i)=>Number($('f'+i).value));if(!validate(values)){message('Enter valid values within the allowed ranges.');return;}const p=score(values);$('prediction').textContent=`${p>=threshold?'ANOMALY DETECTED':'NORMAL TRAFFIC'} · Score ${p.toFixed(4)} · Threshold ${threshold.toFixed(2)} · Inference ${lastLatency.toFixed(2)} ms. Review the flow context before drawing security conclusions.`;};
$('example').onclick=()=>{if(!data)return;const r=data.find(r=>r.probability>.95);r.values.forEach((v,i)=>$('f'+i).value=v);message('Synthetic anomaly example loaded.');};
$('csvFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;batch=[];$('downloadBatch').disabled=true;try{if(!model)throw Error('Model is still loading');if(f.size>5*1024*1024)throw Error('File exceeds 5 MB');const values=parseCSV(await f.text(),model.features);const start=performance.now();batch=values.map((v,i)=>({row:i+2,values:v,probability:predict(model,v)}));const n=batch.filter(r=>r.probability>=threshold).length;$('csvStatus').textContent=`${batch.length} rows analyzed · ${n} anomalies · ${batch.length-n} normal · ${(performance.now()-start).toFixed(1)} ms total. Threshold ${threshold.toFixed(2)}. Label columns were not used for predictions.`;$('downloadBatch').disabled=false;}catch(err){$('csvStatus').textContent='Upload rejected: '+err.message;}};
$('downloadBatch').onclick=()=>{const csv=[model.features.concat(['anomaly_score','prediction','threshold']).join(','),...batch.map(r=>[...r.values,r.probability.toFixed(6),r.probability>=threshold?'anomaly':'normal',threshold].join(','))].join('\n');download('sentinel-predictions.csv',csv,'text/csv');};
async function init(){try{const responses=await Promise.all([fetch('model.json'),fetch('evaluation.json')]);if(responses.some(r=>!r.ok))throw Error('Model files could not be loaded');[model,data]=await Promise.all(responses.map(r=>r.json()));$('engine').textContent='Ready · 40 trees';$('loading').hidden=true;$('play').disabled=false;$('holdoutF1').textContent=pct(model.metrics['Random Forest'].f1);$('featureInputs').innerHTML=labels.map((label,i)=>`<label for="f${i}">${label}<input id="f${i}" type="number" min="0" max="${limits[i]}" step="any" value="${defaults[i]}" required></label>`).join('');$('schema').textContent=model.features.join(', ');$('importance').innerHTML=model.importance.map((v,i)=>({v,i})).sort((a,b)=>b.v-a.v).map(({v,i})=>`<div class="importance-row"><div><span>${labels[i]}</span><b>${pct(v)}</b></div><div class="importance-track"><i style="width:${v*100}%"></i></div></div>`).join('');$('comparison').innerHTML=Object.entries(model.metrics).map(([name,m])=>`<tr><td>${name}</td>${['accuracy','precision','recall','f1','roc_auc'].map(k=>`<td>${pct(m[k])}</td>`).join('')}</tr>`).join('');modelView();render();}catch(err){$('loading').textContent='Unable to initialize: '+err.message+'. Reload the page to retry.';$('engine').textContent='Unavailable';}}
init();
